// The shell: configure, authenticate, and route between the two views.
//
// ROUTING IS THE URL. No `?repo=` and a roster with more than one member means the
// fleet; anything else means that repo. So the fleet page is what a fleet deployment
// opens on, a single-member deployment goes straight to its own dashboard with no
// pointless one-row overview, and every view is a link someone can send.

import * as gh from './github.mjs';
import * as auth from './auth.mjs';
import { loadConfig, loadRoster } from './config.mjs';
import { clearAll, stats } from './cache.mjs';
import { $, el } from './ui.mjs';
import { loadRepo } from './view-repo.mjs';
import { loadFleet } from './view-fleet.mjs';

let CONFIG = null;
let ROSTER = [];

const showError = (msg) => $('errors').append(el('div', { className: 'err', textContent: msg }));

const repoParam = () => new URL(location.href).searchParams.get('repo');
const wantsFleet = () => !repoParam() && ROSTER.length > 1;
const currentRepo = () => repoParam() || CONFIG?.defaultRepo || ROSTER[0] || '';

function go(repo) {
  const url = new URL(location.href);
  if (repo) url.searchParams.set('repo', repo);
  else url.searchParams.delete('repo');
  history.pushState(null, '', url);
  render();
}

// --- chrome ---------------------------------------------------------------------

function renderAuth(viewer) {
  const box = $('auth');
  box.replaceChildren();

  if (viewer) {
    box.append(
      el('img', { className: 'avatar', src: viewer.avatar_url, alt: '', width: 22, height: 22 }),
      el('span', { className: 'hint', textContent: viewer.login }),
      el('button', { textContent: 'Sign out', onclick: () => { auth.signOut(); location.reload(); } }),
    );
    return;
  }
  if (auth.isOAuthConfigured(CONFIG)) {
    box.append(el('button', { className: 'primary', textContent: 'Sign in with GitHub', onclick: () => auth.beginSignIn(CONFIG) }));
    return;
  }
  const input = el('input', { type: 'password', placeholder: 'GitHub token', autocomplete: 'off' });
  const use = () => { auth.setPastedToken(input.value); render(); };
  input.addEventListener('keydown', (e) => { if (e.key === 'Enter') use(); });
  box.append(input, el('button', { textContent: 'Use token', onclick: use }));
}

// The breadcrumb is the way back out of a deep dive, and it only exists when there is
// somewhere to go back to.
function renderCrumb(repo) {
  const crumb = $('crumb');
  crumb.replaceChildren();
  if (!repo || ROSTER.length <= 1) { crumb.hidden = true; return; }
  crumb.hidden = false;
  crumb.append(
    el('a', { href: '?', textContent: '← Fleet', onclick: (e) => { e.preventDefault(); go(null); } }),
    el('span', { className: 'sep', textContent: '/' }),
    el('select', {
      title: 'Switch repository',
      onchange: (e) => go(e.target.value),
    }, [...new Set([repo, ...ROSTER])].sort().map((n) =>
      el('option', { value: n, textContent: n, selected: n === repo }))),
  );
}

const showView = (which) => {
  $('fleet-view').hidden = which !== 'fleet';
  $('repo-view').hidden = which !== 'repo';
};

function footer(parts) {
  const c = stats();
  // The bar carries the short version; the footer below carries the full accounting.
  $('rate').textContent = Number.isFinite(gh.rate.remaining)
    ? `${gh.rate.remaining} left · ${gh.rate.spent} spent`
    : '';
  $('footnote').textContent = [
    ...parts,
    `this load: ${gh.rate.spent} API calls, ${gh.rate.revalidated} revalidated free, ${gh.rate.served} from cache`,
    `cache ${(c.bytes / 1024).toFixed(0)}KB in ${c.entries} entries`,
    `read ${new Date().toISOString().replace('T', ' ').slice(0, 16)}Z`,
  ].join(' · ');
}

// --- render ---------------------------------------------------------------------

let inFlight = false;

async function render() {
  if (inFlight) return;
  inFlight = true;
  $('errors').replaceChildren();
  $('reload').disabled = true;

  const token = auth.currentToken();
  let viewer = null;
  try {
    if (token) viewer = await gh.getViewer(token);
  } catch (e) {
    if (e.status === 401) { auth.signOut(); showError('That credential is no longer valid — sign in again.'); }
  }
  renderAuth(viewer);

  try {
    if (wantsFleet()) {
      renderCrumb(null);
      showView('fleet');
      $('footnote').textContent = `Reading ${ROSTER.length} members…`;
      await loadFleet({
        repos: ROSTER,
        token,
        config: CONFIG,
        onOpen: go,
        onError: showError,
        onProgress: (done, total, repo) => { $('footnote').textContent = `Reading ${done}/${total} — ${repo}…`; },
      });
      footer([`${ROSTER.length} members`]);
    } else {
      const repo = currentRepo();
      if (!/^[^/\s]+\/[^/\s]+$/.test(repo)) {
        showError('No repo selected. Add ?repo=owner/name, or configure a roster.');
        $('footnote').textContent = '';
        return;
      }
      renderCrumb(repo);
      showView('repo');
      $('footnote').textContent = `Reading ${repo}…`;
      const r = await loadRepo({ repo, token, onError: showError });
      footer([
        `${repo} @ ${r.branch} (${r.sha.slice(0, 7)})`,
        `${r.taskCount} declared tasks`,
        `${r.itemCount} work items in the ${r.issuePage.complete
          ? `full issue history (${r.issuePage.scanned} issues)`
          : `most recent ${r.issuePage.scanned} issues — older history not scanned`}`,
      ]);
    }
    $('setup').open = false;
  } catch (e) {
    showError(e.message ?? String(e));
    if (e.status === 401 || e.status === 403) {
      showError(auth.isOAuthConfigured(CONFIG)
        ? 'Sign in with an account that can read this.'
        : 'That token cannot read this — it needs read-only Contents, Issues and Actions.');
    }
    $('footnote').textContent = '';
  } finally {
    inFlight = false;
    $('reload').disabled = false;
  }
}

// --- boot ---------------------------------------------------------------------

async function boot() {
  CONFIG = await loadConfig();

  // Handle an OAuth landing before anything reads the credential.
  const back = await auth.completeSignIn(CONFIG);
  if (back.status === 'error') showError(back.message);

  ROSTER = await loadRoster(CONFIG);
  renderAuth(null);

  $('reload').addEventListener('click', render);
  $('purge').addEventListener('click', () => { clearAll(); render(); });
  $('theme').addEventListener('click', () => {
    const dark = matchMedia('(prefers-color-scheme: dark)').matches;
    const cur = document.documentElement.dataset.theme || (dark ? 'dark' : 'light');
    document.documentElement.dataset.theme = cur === 'dark' ? 'light' : 'dark';
  });
  // Back/forward move between the fleet and a deep dive, because the views are URLs.
  addEventListener('popstate', render);

  if (auth.currentToken() || ROSTER.length || repoParam()) render();
  else { showView('repo'); $('setup').open = true; }
}

boot();
// How the page gets a credential. Two providers, chosen by configuration.
//
// WHAT IS NOT POSSIBLE, because it is the first thing anyone asks for: a static
// page CANNOT reuse the viewer's existing github.com login. Session cookies belong
// to github.com and are not sent to api.github.com, and the API does not accept
// cookie auth cross-origin under any circumstances. "Already logged in" is not a
// credential a browser can spend, so there is no configuration that avoids an
// explicit sign-in of some kind.
//
// What IS possible is making that sign-in a BUTTON rather than a paste box, which
// is the `oauth` provider below: the viewer clicks Sign in, GitHub asks them to
// authorize (once), and everything after runs as them, with exactly the repos and
// permissions their account already has. That is the honest version of "the current
// user's logged-in permissions".
//
// The one piece that cannot live here: exchanging the returned `code` for a token
// needs the app's client secret, and GitHub's token endpoint sends no CORS headers,
// so a browser cannot make that call even if the secret were public. It therefore
// happens at a configured `exchangeUrl` — a few lines of serverless function whose
// only job is that swap. It never sees repo data: once the token is back, the page
// talks to GitHub directly.
//
// `token` remains as the fallback for local development and for anyone who would
// rather paste a PAT than register an app.

const STATE_KEY = 'claudinite-dashboard:oauth-state';
const TOKEN_KEY = 'claudinite-dashboard:token';

// The credential lives in sessionStorage, not localStorage: it is a user access
// token, it should die with the tab, and it must not outlive the browser session on
// a shared machine. The PAT provider deliberately uses the same store — a pasted
// token is no less sensitive for having been typed.
const store = {
  get() { try { return sessionStorage.getItem(TOKEN_KEY) || ''; } catch { return ''; } },
  set(t) { try { t ? sessionStorage.setItem(TOKEN_KEY, t) : sessionStorage.removeItem(TOKEN_KEY); } catch { /* private mode */ } },
};

export const currentToken = () => store.get();
export const signOut = () => store.set('');

// A `remember me` box would mean localStorage, and a token that survives the tab is
// a different security decision than this page is entitled to make on the viewer's
// behalf. Kept explicit so the omission reads as a choice.

const randomState = () => {
  const b = new Uint8Array(16);
  crypto.getRandomValues(b);
  return [...b].map((x) => x.toString(16).padStart(2, '0')).join('');
};

export function isOAuthConfigured(config) {
  return Boolean(config?.clientId && config?.exchangeUrl);
}

// Send the viewer to GitHub. `state` is stored and checked on return — without it,
// a third party could hand the viewer a crafted callback URL and have the page
// exchange a code that is not theirs.
export function beginSignIn(config) {
  const state = randomState();
  try { sessionStorage.setItem(STATE_KEY, state); } catch { /* private mode */ }
  const url = new URL('https://github.com/login/oauth/authorize');
  url.searchParams.set('client_id', config.clientId);
  url.searchParams.set('redirect_uri', config.redirectUri ?? location.origin + location.pathname);
  url.searchParams.set('state', state);
  // A GitHub App's user token carries the app's installed permissions, so no scope
  // is requested there. A classic OAuth App needs to ask, and read-only is the
  // narrowest that can see private repos' issues and runs.
  if (config.scope) url.searchParams.set('scope', config.scope);
  location.assign(url.toString());
}

// Handle a `?code=` landing. Returns:
//   { status: 'signed-in' }              — a token was obtained and stored
//   { status: 'none' }                   — this was not a callback; carry on
//   { status: 'error', message }         — a callback that failed, with the reason
//
// The URL is scrubbed either way: a `code` left in the address bar gets copied into
// chat messages and browser history, and it is a credential until it is spent.
export async function completeSignIn(config, { search = location.search, replaceUrl = true } = {}) {
  const params = new URLSearchParams(search);
  const code = params.get('code');
  const returnedState = params.get('state');
  const oauthError = params.get('error');

  const scrub = () => {
    if (!replaceUrl) return;
    const url = new URL(location.href);
    for (const k of ['code', 'state', 'error', 'error_description']) url.searchParams.delete(k);
    history.replaceState(null, '', url);
  };

  if (oauthError) {
    scrub();
    return { status: 'error', message: params.get('error_description') || oauthError };
  }
  if (!code) return { status: 'none' };

  let expected = null;
  try { expected = sessionStorage.getItem(STATE_KEY); } catch { /* private mode */ }
  try { sessionStorage.removeItem(STATE_KEY); } catch { /* ignore */ }

  // A mismatch is not a retryable error — it means this callback was not started by
  // this tab, so the code is not spent and the viewer is told to start again.
  if (!expected || expected !== returnedState) {
    scrub();
    return { status: 'error', message: 'Sign-in state did not match. Start the sign-in again from this page.' };
  }

  try {
    const res = await fetch(config.exchangeUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
      body: JSON.stringify({ code, redirect_uri: config.redirectUri ?? location.origin + location.pathname }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok || !data.access_token) {
      scrub();
      return { status: 'error', message: data.error_description || data.error || `Token exchange failed (HTTP ${res.status}).` };
    }
    store.set(data.access_token);
    scrub();
    return { status: 'signed-in' };
  } catch (e) {
    scrub();
    return { status: 'error', message: `Token exchange unreachable — ${e.message}` };
  }
}

export const setPastedToken = (t) => store.set(String(t ?? '').trim());
// Where the page gets its deployment-specific facts. Everything host-specific lives
// in a `dashboard.config.json` beside the page, never in the code — the same mounted
// dashboard serves a member repo checked out locally and a fleet-wide Pages site,
// and only the config differs.
//
// Absent config is a valid deployment, not a broken one: it means the token-paste
// provider and whatever repo the URL names. So every key here is optional and every
// miss is a plain default.
//
// Shape:
//   {
//     "clientId":    "Iv1.abc123",                       // GitHub App / OAuth App client id
//     "exchangeUrl": "https://…/github-oauth",           // the code→token endpoint
//     "redirectUri": "https://owner.github.io/Repo/",    // defaults to this page's URL
//     "scope":       "repo",                             // classic OAuth Apps only
//     "rosterUrl":   "./fleet-roster.GENERATED.json",    // the repo selector's source
//     "repos":       ["owner/a", "owner/b"],             // an inline roster instead
//     "defaultRepo": "owner/a"
//   }

export const DEFAULTS = {
  clientId: null,
  exchangeUrl: null,
  redirectUri: null,
  scope: null,
  rosterUrl: null,
  repos: [],
  defaultRepo: null,
};

export async function loadConfig(url = './dashboard.config.json') {
  try {
    const res = await fetch(url, { cache: 'no-store' });
    if (!res.ok) return { ...DEFAULTS };
    return { ...DEFAULTS, ...(await res.json()) };
  } catch {
    return { ...DEFAULTS };
  }
}

// The repo list for the selector. Three sources, in precedence order: an explicit
// inline list, a roster artifact, or nothing — and "nothing" is a single-repo
// deployment, which is the member case.
//
// A roster is read for its KEYS under `repos` when it is a fleet artifact (the shape
// Shepherd already generates), or as a plain array of names. Both are accepted
// because the artifact's job is not to serve this page and its shape is not ours to
// dictate.
export function rosterFrom(doc) {
  if (Array.isArray(doc)) return doc.filter((x) => typeof x === 'string');
  if (Array.isArray(doc?.repos)) return doc.repos.filter((x) => typeof x === 'string');
  if (doc?.repos && typeof doc.repos === 'object') return Object.keys(doc.repos);
  return [];
}

export async function loadRoster(config) {
  if (config.repos?.length) return config.repos;
  if (!config.rosterUrl) return [];
  try {
    const res = await fetch(config.rosterUrl, { cache: 'no-store' });
    if (!res.ok) return [];
    return rosterFrom(await res.json());
  } catch {
    return [];
  }
}

