    color-scheme: light;
    --plane:      #f9f9f7;
    --surface:    #fcfcfb;
    --ink:        #0b0b0b;
    --ink-2:      #52514e;
    --muted:      #898781;
    --rule:       #e1e0d9;
    --border:     rgba(11,11,11,0.10);

    --good:     #0ca30c;
    --warning:  #fab219;
    --serious:  #ec835a;
    --critical: #d03b3b;

    --s-blue:   #2a78d6;
    --s-orange: #eb6834;
    --s-aqua:   #1baf7a;
    --s-yellow: #eda100;
    --s-violet: #4a3aa7;
  }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      color-scheme: dark;
      --plane:   #0d0d0d;
      --surface: #1a1a19;
      --ink:     #ffffff;
      --ink-2:   #c3c2b7;
      --muted:   #898781;
      --rule:    #2c2c2a;
      --border:  rgba(255,255,255,0.10);
      --s-blue:   #3987e5;
      --s-orange: #d95926;
      --s-aqua:   #199e70;
      --s-yellow: #c98500;
      --s-violet: #9085e9;
    }
  }
  :root[data-theme="dark"] {
    color-scheme: dark;
    --plane:   #0d0d0d;
    --surface: #1a1a19;
    --ink:     #ffffff;
    --ink-2:   #c3c2b7;
    --muted:   #898781;
    --rule:    #2c2c2a;
    --border:  rgba(255,255,255,0.10);
    --s-blue:   #3987e5;
    --s-orange: #d95926;
    --s-aqua:   #199e70;
    --s-yellow: #c98500;
    --s-violet: #9085e9;
  }

  * { box-sizing: border-box; }
  body {
    margin: 0;
    background: var(--plane);
    color: var(--ink);
    font: 14px/1.5 system-ui, -apple-system, "Segoe UI", sans-serif;
  }
  a { color: var(--s-blue); }
  h1 { font-size: 17px; margin: 0; letter-spacing: -0.01em; }
  h2 { font-size: 13px; margin: 0 0 10px; color: var(--ink-2); font-weight: 600;
       text-transform: uppercase; letter-spacing: 0.06em; }
  .wrap { max-width: 1180px; margin: 0 auto; padding: 18px 20px 64px; }

  /* --- controls --- */
  /* `topbar`, not `bar`: `.bar` is the outcome mini-chart below, and a header
     sharing that name inherits its 7px×108px geometry. */
  header.topbar {
    position: sticky; top: 0; z-index: 5;
    background: var(--surface);
    border-bottom: 1px solid var(--rule);
  }
  .topbar-in { max-width: 1180px; margin: 0 auto; padding: 12px 20px;
               display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
  .grow { flex: 1 1 auto; }
  input, button, select {
    font: inherit; color: var(--ink); background: var(--surface);
    border: 1px solid var(--border); border-radius: 7px; padding: 6px 9px;
  }
  input { min-width: 190px; }
  select { max-width: 260px; }
  button { cursor: pointer; }
  button:hover { border-color: var(--muted); }
  button[disabled] { opacity: .5; cursor: default; }
  button.primary { background: var(--s-blue); border-color: var(--s-blue); color: #fff; font-weight: 600; }
  .hint { color: var(--muted); font-size: 12px; }
  .authbox { display: inline-flex; align-items: center; gap: 8px; }
  .avatar { border-radius: 50%; display: block; }

  /* --- stat tiles: the headline numbers, no chart needed --- */
  .tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(148px, 1fr));
           gap: 10px; margin-bottom: 22px; }
  .tile { background: var(--surface); border: 1px solid var(--border);
          border-radius: 10px; padding: 12px 14px; }
  .tile .v { font-size: 25px; line-height: 1.15; }
  .tile .k { font-size: 12px; color: var(--ink-2); margin-top: 2px; }

  /* --- panels & tables --- */
  section { margin-bottom: 26px; }
  .panel { background: var(--surface); border: 1px solid var(--border);
           border-radius: 10px; overflow: hidden; }
  table { width: 100%; border-collapse: collapse; }
  th { text-align: left; font-size: 11px; text-transform: uppercase;
