+  await assert.rejects(() => gh.getRepo('o/cold', 't'), (e) => e.status === 'budget');
+  assert.equal(calls, 1);
+});
+
+test('a 403 with nothing left stops the sweep instead of failing member by member', async () => {
+  const gh = await load();
+  const paths = [];
+  globalThis.fetch = async (url) => {
+    paths.push(url);
+    return res({ message: 'API rate limit exceeded' }, {
+      status: 403,
+      headers: { 'x-ratelimit-remaining': '0', 'x-ratelimit-limit': '60', 'x-ratelimit-reset': String(Math.floor(Date.now() / 1000) + 600) },
+    });
+  };
+
+  await assert.rejects(() => gh.getRepo('o/a', 't'));
+  assert.ok(gh.rate.exhaustedUntil > Date.now(), 'the exhaustion is latched');
+
+  // Eleven more members must not each spend a request discovering the same thing —
+  // requests made are what the SECONDARY limit counts, so retrying is the one thing
+  // that can make a rate limit worse.
+  await assert.rejects(() => gh.getRepo('o/b', 't'), (e) => e.status === 'budget');
+  assert.equal(paths.length, 1);
+});
+
+test('the budget survives a page load, so a fresh tab plans before it spends', async () => {
+  const gh = await load();
+  globalThis.fetch = async () => res({ default_branch: 'main' }, {
+    headers: { 'x-ratelimit-remaining': '12', 'x-ratelimit-limit': '60', 'x-ratelimit-reset': '99999' },
+  });
+  await gh.getRepo('o/r', 't');
+
+  const fresh = await load();               // a new module instance is a new tab
+  assert.equal(fresh.rate.remaining, null, 'nothing is known before it is restored');
+  fresh.restoreRate();
+  assert.equal(fresh.rate.remaining, 12);
+  assert.equal(fresh.rate.limit, 60);
+});
+
+test('the preflight reads the budget without spending any of it', async () => {
+  const gh = await load();
+  globalThis.fetch = async (url) => {
+    assert.match(url, /\/rate_limit$/);
+    return res({ resources: { core: { limit: 5000, remaining: 4321, reset: 12345 } } }, { headers: {} });
+  };
+  const out = await gh.preflightRate('t');
+  assert.equal(out.remaining, 4321);
+  assert.equal(gh.rate.limit, 5000);
+  assert.equal(gh.rate.spent, 0, 'the preflight is not charged to the load');
+});
+
+test('history pages are withheld before the live queue is', async () => {
+  const gh = await load();
+  const full = Array.from({ length: 100 }, (_, i) => ({ number: i + 1, title: `i${i}`, state: 'closed', labels: [], body: '' }));
+  let calls = 0;
+  globalThis.fetch = async () => { calls += 1; return res(full, { headers: { etag: 'W/"p"' } }); };
+
+  gh.setPolicy({ spendCeiling: 1 });
+  const out = await gh.listIssues('o/r', 't', { pages: 5 });
+  assert.equal(calls, 1, 'page 1 — the whole open queue — is still read');
+  assert.equal(out.issues.length, 100);
+  assert.equal(gh.rate.withheld, 1, 'the settled history behind it is what goes without');
+});

input.body:
The dashboard caches well but still *asks* on every load: an ETag revalidation costs no primary budget, yet it is a request, and a cold entry has nothing to revalidate. A twelve-member sweep is ~75 requests. Unauthenticated that is 60/hour — over budget on the first load, and the rest of the hour renders "unreadable" rows for repos that are fine.

**Ask:** the page should decide up front how much it may spend, and when the budget is low, a full page refresh should make **no requests at all** for a stated window.

Shape:
- a staleness floor (`minAge`) — under pressure a cached entry younger than the floor is served without any request, conditional ones included;
- the floor reaches the rate-limit **reset** when the budget is scarce, so reloading is free until the window rolls;
- a spend ceiling that always reserves the viewer's last requests for the rest of their hour;
- the free `GET /rate_limit` preflight, plus the budget carried across page loads, so a fresh tab plans before it spends rather than discovering the limit by hitting it;
- a 403/429 with nothing left latches, so eleven more members do not each spend a request learning the same thing (requests made are what the secondary limit counts);
- the mode is stated in the UI — a page silently serving hour-old data is worse than one that refuses.

Docs this follows: [rate limits](https://docs.github.com/en/rest/using-the-rest-api/rate-limits-for-the-rest-api), [best practices](https://docs.github.com/en/rest/using-the-rest-api/best-practices-for-using-the-rest-api).

The `sheepdog` fleet-digest task already writes a morning brief per day at `digests/<date>.md` — the few things the fleet actually accomplished, plus the project worth returning to. Nothing surfaces it; the dashboard is where someone is already looking.

Show **yesterday's and the day before's**, rendered from the two dated files. Both are content at a path in a repo, so they are immutable-cacheable by sha and cost nothing on a warm load.

Open points:
- which repo holds `digests/` — the fleet enforcer's, so it needs a config key rather than a hardcoded name;
- a missing file is a normal state (the task had nothing to report, or has not run yet) and must read as such, never as an error;
- the digest is Markdown, and the page has no renderer today — the smallest honest option is headings + paragraphs + links, not a Markdown library.

Every panel on the fleet page answers "where do I need to look". Nothing answers "what has this fleet been doing" — and after a good week the page looks identical to a dead one, because healthy means every count is zero.

Wanted: a top-level activity read, graphed rather than tabulated. Candidates, cheapest first:
- work items closed per day across the fleet, stacked by outcome (already in the issue reads — no new requests);
- commits to each member's default branch per day (`/repos/{r}/commits` is one call per member, or free from the existing head-sha read at day granularity);
- runs per day and their pass rate;
- which members moved at all — a fleet where two of twelve are active is a fact about the fleet.

Constraint that shapes it: it must come from reads the page **already makes**, or it undoes #995. Anything needing a per-member extra call has to justify itself against the anonymous 60/hour case.

