1	// How much of the viewer's GitHub rate limit this page is allowed to spend, and what
2	// it does instead when it cannot afford a live read. Pure: no clock of its own, no
3	// I/O, no DOM — `github.mjs` enforces what this decides.
4	//
5	// WHY A POLICY AT ALL, when `cache.mjs` already caches everything. Because the two
6	// credentials this page runs under differ by a factor of eighty-three:
7	//
8	//   unauthenticated   60 requests/hour, per IP address
9	//   a user token   5,000 requests/hour, per user (shared across every app they use)
10	//
11	// A fleet sweep costs roughly six requests per member on a cold cache. Twelve members
12	// is ~72 — over the anonymous budget for the whole hour on the FIRST load, and the
13	// page then spends the rest of that hour rendering "unreadable" rows for repos that
14	// are perfectly fine. Caching alone does not save it, because the existing strategies
15	// all still make a request: an ETag revalidation is free of the PRIMARY limit but it
16	// is still a request, and a cold entry has nothing to revalidate.
17	//
18	// So the policy adds the one thing the cache layer cannot decide on its own: a
19	// STALENESS FLOOR. Under pressure, an entry younger than `minAge` is served without
20	// asking GitHub at all — no request, not even a conditional one. That is what makes
21	// "reload the page and it costs nothing for the next X minutes" true rather than
22	// merely cheap.
23	//
24	// The ladder is driven by HEADROOM — the remaining budget measured in whole page
25	// loads, not in requests — because "1,400 left" means something different to a
26	// one-repo page than to a forty-member fleet.
27	
28	// Requests one member costs on a cold cache: repo metadata, head sha, the
29	// declaration, the tree, one issues page, one runs page. A warm member costs fewer
30	// and a not-adopted one costs three, so this is the ceiling rather than the average —
31	// budgeting against the ceiling is what keeps the last member on the list readable.
32	export const COST_PER_MEMBER = 6;
33	
34	// The page's own fixed overhead: the viewer, plus the canon reference the fleet's
35	// mount column compares against.
36	export const COST_FIXED = 3;
37	
38	export const MINUTE_MS = 60e3;
39	export const HOUR_MS = 3600e3;
40	export const DAY_MS = 24 * HOUR_MS;
41	
42	// What a dashboard load must never do: spend the viewer's LAST requests. Whatever is
43	// held back here is what is left for the rest of their hour — another tab, a CLI, the
44	// next page they open. Ten percent, floored at five so an anonymous 60 keeps six, and
45	// capped at fifty so a 5,000 budget does not hold back five hundred.
46	export const reserveFor = (limit) =>
47	  (Number.isFinite(limit) && limit > 0 ? Math.min(50, Math.max(5, Math.ceil(limit * 0.1))) : 5);
48	
49	// The tier a limit implies. Read off `x-ratelimit-limit` rather than off whether a
50	// token was supplied, because those disagree in exactly the case that matters: a
51	// token the server rejected reports the anonymous limit while the page still believes
52	// it is signed in.
53	export function classify(limit) {
54	  if (!Number.isFinite(limit)) return 'unknown';
55	  if (limit <= 60) return 'anonymous';
56	  if (limit <= 1000) return 'workflow';      // an Actions GITHUB_TOKEN, per repository
57	  return 'user';                             // a user or installation token
58	}
59	
60	export const estimateCost = (memberCount) => COST_FIXED + COST_PER_MEMBER * Math.max(1, memberCount);
61	
62	// The modes, worst last. Each names what the page will DO, not how alarmed it is.
63	export const MODES = ['live', 'tight', 'low', 'scarce', 'frozen'];
64	
65	const CEIL_MIN_AGE = HOUR_MS;   // a reset is at most an hour out, so nothing is held longer
66	
67	// The decision. `remaining`/`limit`/`reset` are the last thing GitHub said (any of
68	// them may be null, which is "we have not asked yet"), `memberCount` sizes the load,
69	// and `now` is supplied so this stays pure.
70	//
71	// Returns:
72	//   mode          which rung of the ladder
73	//   minAge        a cached entry younger than this is served WITHOUT a request
74	//   historyTtl    how long settled issue history stays good
75	//   spendCeiling  how many rate-limit-spending requests this load may make
76	//   reason        one sentence, shown to the viewer — the page never silently throttles
77	export function planPolicy({ remaining = null, limit = null, reset = null, memberCount = 1, now = Date.now() } = {}) {
78	  const cost = estimateCost(memberCount);
79	  const tier = classify(limit);
80	  const msToReset = Number.isFinite(reset) ? Math.max(0, reset * 1000 - now) : null;
81	  const untilReset = Math.min(msToReset ?? CEIL_MIN_AGE, CEIL_MIN_AGE);
82	
83	  // Nothing known yet — the first load of the first tab. Read live; the very first
84	  // response teaches us the budget and every load after this one is planned.
85	  if (!Number.isFinite(remaining)) {
86	    return {
87	      mode: 'live', tier, cost, minAge: 0, historyTtl: DAY_MS, spendCeiling: Infinity,
88	      reason: 'budget not known yet — reading live',
89	    };
90	  }
91	
92	  const reserve = reserveFor(limit);
93	  const spendable = Math.max(0, remaining - reserve);
94	  const headroom = spendable / cost;
95	
96	  if (spendable <= 0) {
97	    return {
